import { readFile, writeFile, mkdir, rename } from "node:fs/promises";
import { dirname } from "node:path";
import { randomUUID } from "node:crypto";

const LIMITS = { title: 300, author: 300, notes: 5000 };
const STATUSES = ["reading", "finished"];

function badRequest(message) {
  const err = new Error(message);
  err.status = 400;
  return err;
}

function notFound(message) {
  const err = new Error(message);
  err.status = 404;
  return err;
}

function cleanText(value, field, { required = false, max = LIMITS[field] } = {}) {
  if (value === undefined || value === null || value === "") {
    if (required) throw badRequest(`${field} is required`);
    return "";
  }
  if (typeof value !== "string") throw badRequest(`${field} must be a string`);
  const trimmed = value.trim();
  if (!trimmed && required) throw badRequest(`${field} is required`);
  if (trimmed.length > max) throw badRequest(`${field} must be at most ${max} characters`);
  return trimmed;
}

export function createStore(dataFile) {
  let queue = Promise.resolve();

  async function loadBooks() {
    try {
      const raw = await readFile(dataFile, "utf8");
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed;
      if (Array.isArray(parsed?.books)) return parsed.books;
      return [];
    } catch (err) {
      if (err.code === "ENOENT" || err instanceof SyntaxError) return [];
      throw err;
    }
  }

  async function saveBooks(books) {
    await mkdir(dirname(dataFile), { recursive: true });
    const tmp = `${dataFile}.${process.pid}.${Date.now()}.tmp`;
    await writeFile(tmp, JSON.stringify({ books }, null, 2) + "\n", "utf8");
    await rename(tmp, dataFile);
  }

  function withBooks(mutator) {
    const run = queue.then(async () => {
      const books = await loadBooks();
      const { value, changed = true } = (await mutator(books)) ?? {};
      if (changed) await saveBooks(books);
      return value;
    });
    queue = run.then(
      () => {},
      () => {}
    );
    return run;
  }

  return {
    async list() {
      const books = await withBooks((b) => ({ value: b, changed: false }));
      return books.map((b) => ({ ...b }));
    },

    async get(id) {
      const books = await withBooks((b) => ({ value: b, changed: false }));
      return books.find((b) => b.id === id) ?? null;
    },

    async create(body = {}) {
      return withBooks((books) => {
        const status = body.status === undefined ? "reading" : body.status;
        if (!STATUSES.includes(status)) throw badRequest(`status must be one of: ${STATUSES.join(", ")}`);
        const now = new Date().toISOString();
        const book = {
          id: randomUUID(),
          title: cleanText(body.title, "title", { required: true }),
          author: cleanText(body.author, "author", { required: true }),
          notes: cleanText(body.notes, "notes"),
          status,
          createdAt: now,
          updatedAt: now,
          finishedAt: status === "finished" ? now : null,
        };
        books.push(book);
        return { value: { ...book } };
      });
    },

    async update(id, patch = {}) {
      return withBooks((books) => {
        const book = books.find((b) => b.id === id);
        if (!book) throw notFound("book not found");
        if (patch.title !== undefined) book.title = cleanText(patch.title, "title", { required: true });
        if (patch.author !== undefined) book.author = cleanText(patch.author, "author", { required: true });
        if (patch.notes !== undefined) book.notes = cleanText(patch.notes, "notes");
        if (patch.status !== undefined) {
          if (!STATUSES.includes(patch.status)) throw badRequest(`status must be one of: ${STATUSES.join(", ")}`);
          if (patch.status === "finished" && book.status !== "finished") book.finishedAt = new Date().toISOString();
          if (patch.status === "reading") book.finishedAt = null;
          book.status = patch.status;
        }
        book.updatedAt = new Date().toISOString();
        return { value: { ...book } };
      });
    },
  };
}

import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { extname, join, normalize, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { createStore } from "./lib/store.js";

const root = fileURLToPath(new URL(".", import.meta.url));
const publicDir = join(root, "public");
const dataFile = process.env.DATA_FILE ? fileURLToPath(new URL(process.env.DATA_FILE, `file://${root}`)) : join(root, "books.json");
const port = Number(process.env.PORT || 3000);
const host = process.env.HOST || "127.0.0.1";

const store = createStore(dataFile);

const MIME = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
};

function send(res, status, body, headers = {}) {
  res.writeHead(status, headers);
  res.end(body);
}

function sendJSON(res, status, value) {
  send(res, status, JSON.stringify(value), { "Content-Type": "application/json; charset=utf-8" });
}

function readJSONBody(req, limit = 64 * 1024) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > limit) {
        reject(Object.assign(new Error("payload too large"), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => {
      if (chunks.length === 0) return resolve({});
      try {
        resolve(JSON.parse(Buffer.concat(chunks).toString("utf8")));
      } catch {
        reject(Object.assign(new Error("invalid JSON body"), { status: 400 }));
      }
    });
    req.on("error", reject);
  });
}

function handleError(res, err) {
  const status = err.status && Number.isInteger(err.status) ? err.status : 500;
  sendJSON(res, status, { error: status === 500 ? "internal server error" : err.message });
}

async function serveIndex(res) {
  const html = await readFile(join(publicDir, "index.html"));
  send(res, 200, html, { "Content-Type": MIME[".html"] });
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host ?? "localhost"}`);
    const path = decodeURIComponent(url.pathname);
    const bookAPI = path.match(/^\/api\/books\/([A-Za-z0-9-]+)$/);
    const bookPage = path.match(/^\/books\/([A-Za-z0-9-]+)$/);

    if (path === "/api/books" && req.method === "GET") {
      return sendJSON(res, 200, await store.list());
    }
    if (path === "/api/books" && req.method === "POST") {
      const book = await store.create(await readJSONBody(req));
      return sendJSON(res, 201, book);
    }
    if (bookAPI) {
      const id = bookAPI[1];
      if (req.method === "GET") {
        const book = await store.get(id);
        return book ? sendJSON(res, 200, book) : sendJSON(res, 404, { error: "book not found" });
      }
      if (req.method === "PATCH" || req.method === "PUT") {
        const book = await store.update(id, await readJSONBody(req));
        return sendJSON(res, 200, book);
      }
      return sendJSON(res, 405, { error: "method not allowed" });
    }
    if (path.startsWith("/api/")) {
      return sendJSON(res, 404, { error: "not found" });
    }

    if (req.method !== "GET" && req.method !== "HEAD") {
      return send(res, 405, "method not allowed");
    }

    if (bookPage) {
      return serveIndex(res);
    }

    const requested = path === "/" ? "/index.html" : path;
    const safe = normalize(requested).replace(/^([/\\])+/, "");
    const filePath = join(publicDir, safe);
    if (filePath !== publicDir && !filePath.startsWith(publicDir + sep)) {
      return send(res, 403, "forbidden");
    }
    try {
      const file = await readFile(filePath);
      const type = MIME[extname(filePath)] ?? "application/octet-stream";
      return send(res, 200, file, { "Content-Type": type });
    } catch (err) {
      if (err.code === "ENOENT" || err.code === "EISDIR") {
        return send(res, 404, "not found");
      }
      throw err;
    }
  } catch (err) {
    handleError(res, err);
  }
});

server.listen(port, host, () => {
  console.log(`Bookshelf running at http://${host}:${port}`);
});

const app = document.getElementById("app");

function el(tag, props = {}, children = []) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(props)) {
    if (key === "class") node.className = value;
    else if (key === "text") node.textContent = value;
    else node.setAttribute(key, value);
  }
  for (const child of [].concat(children)) {
    if (child == null) continue;
    node.appendChild(typeof child === "string" ? document.createTextNode(child) : child);
  }
  return node;
}

async function api(path, options = {}) {
  const res = await fetch(path, {
    headers: { "Content-Type": "application/json" },
    ...options,
  });
  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new Error(body.error || `request failed (${res.status})`);
  }
  return res.json();
}

function statusBadge(status) {
  return el("span", { class: `badge ${status}`, text: status === "finished" ? "Finished" : "Reading" });
}

function bookCard(book) {
  const actions = [];
  if (book.status === "reading") {
    actions.push(el("button", { class: "btn small", "data-finish": book.id, text: "Mark finished" }));
  } else {
    actions.push(el("button", { class: "btn small ghost", "data-reopen": book.id, text: "Reading again" }));
  }
  actions.push(el("a", { class: "btn small ghost", href: `/books/${book.id}`, text: "View / share" }));
  return el("li", { class: "card" }, [
    el("a", { class: "card-title", href: `/books/${book.id}`, text: book.title }),
    el("div", { class: "card-author", text: book.author }),
    el("div", { class: "card-row" }, [statusBadge(book.status), ...actions]),
  ]);
}

function addForm() {
  const title = el("input", { name: "title", required: "", maxlength: "300", placeholder: "Title" });
  const author = el("input", { name: "author", required: "", maxlength: "300", placeholder: "Author" });
  const notes = el("textarea", { name: "notes", rows: "3", maxlength: "5000", placeholder: "Notes (optional)" });
  const error = el("p", { class: "form-error", hidden: "" });
  const form = el("form", { class: "add-form", novalidate: "" }, [
    el("h2", { text: "Add a book" }),
    title,
    author,
    notes,
    el("div", { class: "form-row" }, [
      el("button", { class: "btn", type: "submit", text: "Add book" }),
      error,
    ]),
  ]);
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    error.hidden = true;
    try {
      await api("/api/books", {
        method: "POST",
        body: JSON.stringify({
          title: title.value,
          author: author.value,
          notes: notes.value,
        }),
      });
      form.reset();
      await renderList();
    } catch (err) {
      error.textContent = err.message;
      error.hidden = false;
    }
  });
  return form;
}

async function renderList() {
  let books;
  try {
    books = await api("/api/books");
  } catch (err) {
    app.replaceChildren(el("p", { class: "error", text: `Could not load books: ${err.message}` }));
    return;
  }
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");

  const section = (heading, items, emptyText) =>
    el("section", {}, [
      el("h2", { text: heading }),
      items.length
        ? el("ul", { class: "book-list" }, items.map(bookCard))
        : el("p", { class: "empty", text: emptyText }),
    ]);

  app.replaceChildren(
    section("Currently reading", reading, "Nothing on the nightstand yet — add a book below."),
    section("Finished", finished, "No finished books yet."),
    addForm()
  );
}

function copyLinkButton() {
  const btn = el("button", { class: "btn small ghost", text: "Copy link" });
  btn.addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText(location.href);
      btn.textContent = "Copied!";
    } catch {
      btn.textContent = location.href;
      window.prompt("Copy this link:", location.href);
    }
    setTimeout(() => (btn.textContent = "Copy link"), 2000);
  });
  return btn;
}

async function renderDetail(id) {
  let book;
  try {
    book = await api(`/api/books/${id}`);
  } catch (err) {
    app.replaceChildren(
      el("p", { class: "error", text: err.message.includes("not found") ? "No book with that link." : err.message }),
      el("a", { class: "btn", href: "/", text: "Back to bookshelf" })
    );
    return;
  }
  const actions = [
    book.status === "reading"
      ? el("button", { class: "btn", "data-finish": book.id, text: "Mark finished" })
      : el("button", { class: "btn ghost", "data-reopen": book.id, text: "Reading again" }),
    copyLinkButton(),
  ];
  app.replaceChildren(
    el("p", {}, [el("a", { href: "/", text: "← All books" })]),
    el("article", { class: "detail" }, [
      el("h2", { text: book.title }),
      el("p", { class: "detail-author", text: `by ${book.author}` }),
      el("p", {}, [statusBadge(book.status)]),
      el("h3", { text: "Notes" }),
      book.notes
        ? el("p", { class: "notes", text: book.notes })
        : el("p", { class: "empty", text: "No notes yet." }),
      el("div", { class: "form-row" }, actions),
    ])
  );
}

document.addEventListener("click", async (event) => {
  const finish = event.target.closest("[data-finish], [data-reopen]");
  if (!finish) return;
  const status = finish.hasAttribute("data-finish") ? "finished" : "reading";
  const id = finish.dataset.finish ?? finish.dataset.reopen;
  finish.disabled = true;
  try {
    await api(`/api/books/${id}`, { method: "PATCH", body: JSON.stringify({ status }) });
    const match = location.pathname.match(/^\/books\/([A-Za-z0-9-]+)$/);
    if (match) await renderDetail(match[1]);
    else await renderList();
  } catch (err) {
    alert(err.message);
    finish.disabled = false;
  }
});

const bookRoute = location.pathname.match(/^\/books\/([A-Za-z0-9-]+)$/);
if (bookRoute) renderDetail(bookRoute[1]);
else if (location.pathname === "/") renderList();
else app.replaceChildren(el("p", { text: "Not found." }), el("a", { class: "btn", href: "/", text: "Back to bookshelf" }));

:root {
  color-scheme: light;
  --ink: #1f2430;
  --muted: #6b7280;
  --line: #e5e7eb;
  --bg: #f7f6f3;
  --card: #ffffff;
  --accent: #3563e9;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.5;
}

header {
  padding: 1rem 1.25rem;
  border-bottom: 1px solid var(--line);
  background: var(--card);
}

.brand {
  font-weight: 700;
  text-decoration: none;
  color: var(--ink);
}

main {
  max-width: 720px;
  margin: 0 auto;
  padding: 1.5rem 1.25rem 4rem;
}

h2 {
  font-size: 1.05rem;
  margin: 1.75rem 0 0.75rem;
}

section:first-child h2 {
  margin-top: 0;
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.6rem;
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 0.8rem 1rem;
}

.card-title {
  font-weight: 600;
  color: var(--ink);
  text-decoration: none;
}

.card-title:hover {
  text-decoration: underline;
}

.card-author {
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0.1rem 0 0.5rem;
}

.card-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.badge {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  border-radius: 999px;
  padding: 0.15rem 0.55rem;
}

.badge.reading {
  background: #e8f0fe;
  color: #1a56db;
}

.badge.finished {
  background: #e7f6ec;
  color: #187a3c;
}

.btn {
  display: inline-block;
  font: inherit;
  font-size: 0.9rem;
  padding: 0.4rem 0.8rem;
  border-radius: 8px;
  border: 1px solid var(--accent);
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  text-decoration: none;
}

.btn:hover {
  filter: brightness(0.95);
}

.btn.ghost {
  background: transparent;
  color: var(--accent);
}

.btn.small {
  font-size: 0.8rem;
  padding: 0.25rem 0.6rem;
}

.btn:disabled {
  opacity: 0.6;
  cursor: default;
}

.add-form {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 0.25rem 1rem 1rem;
  margin-top: 2rem;
}

.add-form input,
.add-form textarea {
  display: block;
  width: 100%;
  font: inherit;
  margin-top: 0.6rem;
  padding: 0.45rem 0.6rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
}

.add-form textarea {
  resize: vertical;
}

.form-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: 0.75rem;
  flex-wrap: wrap;
}

.form-error,
.error {
  color: #b91c1c;
}

.empty {
  color: var(--muted);
  font-size: 0.9rem;
}

.detail h2 {
  margin-bottom: 0.1rem;
}

.detail-author {
  color: var(--muted);
  margin: 0 0 0.75rem;
}

.notes {
  white-space: pre-wrap;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 0.8rem 1rem;
}

import { describe, it, before, after } from "vitest";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createStore } from "../lib/store.js";

let dir;
let file;

before(async () => {
  dir = await mkdtemp(join(tmpdir(), "bookshelf-"));
  file = join(dir, "books.json");
});

after(async () => {
  await rm(dir, { recursive: true, force: true });
});

describe("store", () => {
  it("creates a book with defaults", async () => {
    const store = createStore(file);
    const book = await store.create({ title: "  Dune  ", author: "Frank Herbert", notes: " Great opening. " });
    assert.like
    expect(book.title).toBe("Dune");
    expect(book.author).toBe("Frank Herbert");
    expect(book.notes).toBe("Great opening.");
    expect(book.status).toBe("reading");
    expect(book.finishedAt).toBeNull();
    expect(book.id).toBeTruthy();
  });

  it("rejects missing title or author", async () => {
    const store = createStore(file);
    await expect(store.create({ author: "x" })).rejects.toMatchObject({ status: 400 });
    await expect(store.create({ title: "x" })).rejects.toMatchObject({ status: 400 });
    await expect(store.create({ title: "  ", author: "x" })).rejects.toMatchObject({ status: 400 });
  });

  it("persists books across store instances", async () => {
    const first = createStore(file);
    await first.create({ title: "Left Hand of Darkness", author: "Ursula K. Le Guin" });
    const second = createStore(file);
    const books = await second.list();
    expect(books.map((b) => b.title)).toContain("Left Hand of Darkness");
  });

  it("marks a book finished and back", async () => {
    const store = createStore(file);
    const book = await store.create({ title: "Piranesi", author: "Susanna Clarke" });
    const done = await store.update(book.id, { status: "finished" });
    expect(done.status).toBe("finished");
    expect(done.finishedAt).toBeTruthy();
    const reopened = await store.update(book.id, { status: "reading" });
    expect(reopened.status).toBe("reading");
    expect(reopened.finishedAt).toBeNull();
  });

  it("updates notes", async () => {
    const store = createStore(file);
    const book = await store.create({ title: "Project Hail Mary", author: "Andy Weir" });
    const updated = await store.update(book.id, { notes: "love the science" });
    expect(updated.notes).toBe("love the science");
  });

  it("returns 404 for unknown ids", async () => {
    const store = createStore(file);
    expect(await store.get("nope")).toBeNull();
    await expect(store.update("nope", { status: "finished" })).rejects.toMatchObject({ status: 404 });
  });

  it("writes valid JSON to disk", async () => {
    const store = createStore(file);
    await store.create({ title: "Snow Crash", author: "Neal Stephenson" });
    const raw = JSON.parse(await readFile(file, "utf8"));
    expect(Array.isArray(raw.books)).toBe(true);
  });
});

